INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q2786767', 'Battle of Blaauwberg', 'The Battle of Blaauwberg (also known as the Battle of Cape Town) was a successful British amphibious operation during the War of the Third Coalition which lasted from 8–18 January 1806 and resulted in the capture of the Dutch Cape Colony. After defeating their Batavian opponents, the British signed a treaty under the Treaty Tree in Woodstock, Cape Town which established Britain''s control over the Cape Colony.', 1806, 1, 8, 1806, 1, 18, 'day', '8 January 1806 – 18 January 1806', 47, 'https://en.wikipedia.org/wiki/Battle_of_Blaauwberg'),
  ('Q9294875', 'Ndwandwe–Zulu War', 'The Ndwandwe–Zulu War of 1817–1819 was a war fought between the expanding Zulu Kingdom and the Ndwandwe tribe in South Africa. The Zulus were originally a tiny tribe that had migrated to the eastern plateau of present-day South Africa; they became a strong tribal nation largely due to the efforts of an ambitious chieftain named Shaka (c.', 1817, NULL, NULL, 1819, NULL, NULL, 'year', '1817–1819', 39, 'https://en.wikipedia.org/wiki/Ndwandwe%E2%80%93Zulu_War'),
  ('Q3289977', 'Battle of Mhlatuze River', 'The Battle of Mhlatuze River was fought between the Zulu and Ndwandwe tribes in 1820 following the Zulu Civil War. The Ndwandwe hierarchy was set asunder by the battle, and largely scattered their population in response.', 1820, NULL, NULL, NULL, NULL, NULL, 'year', '1820', 39, 'https://en.wikipedia.org/wiki/Battle_of_Mhlatuze_River'),
  ('Q2890303', 'Battle of Vegkop', 'The Battle of Vegkop, alternatively spelled as Vechtkop, took place on 16 October 1836 near the present day town of Heilbron, Free State, South Africa. After an impi of about 600 Matebele murdered 15 to 17 Afrikaner voortrekkers on the Vaal River, abducting three children, King Mzilikazi (c.', 1836, 10, 16, NULL, NULL, NULL, 'day', '16 October 1836', 39, 'https://en.wikipedia.org/wiki/Battle_of_Vegkop'),
  ('Q1392699', 'Battle of Blood River', 'The Battle of Blood River, or Voortrekker–Zulu War, (16 December 1838) was fought on the bank of the Ncome River, in what is today KwaZulu-Natal, South Africa between 464 Voortrekkers ("Pioneers"), led by Andries Pretorius, and an estimated 25,000 to 30,000 Zulu. Estimations of casualties amounted to over 3,000 of King Dingane''s soldiers dead, including two Zulu princes competing with Prince Mpande for the Zulu throne.', 1838, 12, 16, NULL, NULL, NULL, 'day', '16 December 1838', 57, 'https://en.wikipedia.org/wiki/Battle_of_Blood_River'),
  ('Q1464154', 'Weenen massacre', 'The Weenen massacre (Afrikaans: Bloukransmoorde) was the massacre of Voortrekkers, Khoikhoi and Basuto by the Zulu Kingdom on 17 February 1838. The massacres occurred at Doringkop, Bloukrans River, Moordspruit, Rensburgspruit and other sites around the present day town of Weenen in South Africa''s KwaZulu-Natal province.', 1838, 2, 17, NULL, NULL, NULL, 'day', '17 February 1838', 47, 'https://en.wikipedia.org/wiki/Weenen_massacre'),
  ('Q2888334', 'Battle of Congella', 'The Battle of Congella, beginning 23 May 1842, was between the British of the Cape colony and Voortrekkers or the Boer forces of the Natalia Republic. The Republic of Natalia sought an independent port of entry, free from British control and thus sought to conquer the Port Natal trading settlement which had been settled by mostly British merchants in modern-day KwaZulu-Natal.', 1842, 5, 24, NULL, NULL, NULL, 'day', '24 May 1842', 37, 'https://en.wikipedia.org/wiki/Battle_of_Congella'),
  ('Q950121', 'Free State–Basotho War', 'The Free State–Basotho Wars refers to a series of wars fought between King Moshoeshoe I, the ruler of the Basotho Kingdom, and white settlers, in what is now known as the Free State. These can be divided into the Senekal''s War of 1858, the Seqiti War in 1865−1866 and the Third Basotho War in 1867−68.', 1858, NULL, NULL, 1868, NULL, NULL, 'year', '1858–1868', 39, 'https://en.wikipedia.org/wiki/Free_State%E2%80%93Basotho_Wars'),
  ('Q949635', 'Battle of Kambula', 'The Battle of Kambula took place on 29 March 1879, during the Anglo-Zulu War, when a Zulu military force attacked the British camp at Kambula, having routed the mounted element of the British force at the Battle of Hlobane the day before. The battle was a severe Zulu defeat and the warriors lost their belief in victory.', 1879, 3, 29, NULL, NULL, NULL, 'day', '29 March 1879', 50, 'https://en.wikipedia.org/wiki/Battle_of_Kambula'),
  ('Q1670862', 'Battle of Hlobane', 'The Battle of Hlobane (28 March 1879) took place at Hlobane, near the modern town of Vryheid in KwaZulu-Natal, South Africa during the Anglo-Zulu War.', 1879, 3, 28, NULL, NULL, NULL, 'day', '28 March 1879', 43, 'https://en.wikipedia.org/wiki/Battle_of_Hlobane'),
  ('Q2166177', 'Battle of Ulundi', 'The Battle of Ulundi (also known as the Battle of kwaNodwengu or the Battle of oCwecweni) took place at the Zulu capital of Ulundi (Zulu: oNdini) on 4 July 1879 and was the last battle of the Anglo-Zulu War. The British Army broke the military power of the Zulu Kingdom by defeating the main Zulu army and capturing and burning the royal kraal of oNdini.', 1879, 7, 4, NULL, NULL, NULL, 'day', '4 July 1879', 51, 'https://en.wikipedia.org/wiki/Battle_of_Ulundi'),
  ('Q2888632', 'Battle of Gingindlovu', 'The Battle of Gingindlovu (uMgungundlovu) was fought on 2 April 1879 between a British relief column sent to break the Siege of Eshowe and a Zulu impi of King Cetshwayo.', 1879, 4, 2, NULL, NULL, NULL, 'day', '2 April 1879', 39, 'https://en.wikipedia.org/wiki/Battle_of_Gingindlovu'),
  ('Q1348785', 'Basuto Gun War', 'The Basuto Gun War, also known as the Basutoland Rebellion, was a conflict between the Basuto and the British Cape Colony. It lasted from 13 September 1880 to 29 April 1881 and ended in a Basuto victory.', 1880, NULL, NULL, 1881, NULL, NULL, 'year', '1880–1881', 50, 'https://en.wikipedia.org/wiki/Basuto_Gun_War'),
  ('Q741129', 'Battle of Laing''s Nek', 'The Battle of Laing''s Nek was a major battle fought at Laing''s Nek during the First Boer War on 28 January 1881.', 1881, 1, 28, NULL, NULL, NULL, 'day', '28 January 1881', 47, 'https://en.wikipedia.org/wiki/Battle_of_Laing''s_Nek'),
  ('Q1286274', 'Battle of Schuinshoogte', 'Battle of Schuinshoogte, also known as Battle of Ingogo, was fought north of Newcastle, KwaZulu-Natal, on 8 February 1881 during the First Boer War. General Sir George Pomeroy Colley''s communications with Newcastle were under constant harassment by mounted Boer patrols under Commander J. D. Weilbach after the Boer victory at the Battle of Laing''s Nek and as a result he planned to clear a path along the Newcastle–Mount Prospect road to better protect the British supply line, and receive fresh reinforcements he needed to bolster his ranks.', 1881, 2, 8, NULL, NULL, NULL, 'day', '8 February 1881', 47, 'https://en.wikipedia.org/wiki/Battle_of_Schuinshoogte'),
  ('Q2887936', 'Battle of Elandsfontein', 'The Battle of Elandsfontein on 11 January 1881 was a military engagement during the First Boer War which took place at Elandsfontein ridge just west of Pretoria. During the war horses proved to be the main means of transport across the South African plains.', 1881, 1, 16, NULL, NULL, NULL, 'day', '16 January 1881', 37, 'https://en.wikipedia.org/wiki/Battle_of_Elandsfontein'),
  ('Q215112', 'Second Boer War', 'The Second Boer War was a conflict fought between 1899 and 1902 between the British Empire and the Boer republics (the South African Republic and Orange Free State), triggered by the discovery of gold in the Transvaal, specifically the Witwatersrand gold fields, and the ensuing political dispute over the voting rights of British expatriates (Uitlanders). In 1877, the British annexed the bankrupt Transvaal, and the British military neutralized the regional threat of the Zulu Kingdom in 1879 in the Anglo-Zulu War.', 1899, 10, 11, 1902, 5, 31, 'day', '11 October 1899 – 31 May 1902', 79, 'https://en.wikipedia.org/wiki/Second_Boer_War'),
  ('Q247871', 'Battle of Talana Hill', 'The Battle of Talana Hill, also known as the Battle of Glencoe, was the first major clash of the Second Boer War. A frontal attack by British infantry supported by artillery drove the Boers from a hilltop position, but the British suffered heavy casualties in the process, including their commanding general, Sir William Penn Symons, being mortally wounded.', 1899, 10, 20, NULL, NULL, NULL, 'day', '20 October 1899', 45, 'https://en.wikipedia.org/wiki/Battle_of_Talana_Hill'),
  ('Q248979', 'Battle of Modder River', 'The Battle of Modder River (Afrikaans: Slag van die Twee Riviere, lit. ''Battle of the Two Rivers'', fought near the confluence of the Modder and Riet Rivers) was an engagement in the Boer War, fought at Modder River, on 28 November 1899. A British column under Lord Methuen, that was attempting to relieve the besieged town of Kimberley, forced Boers under General Piet Cronjé to retreat to Magersfontein, but suffered heavy casualties altogether.', 1899, 11, 28, NULL, NULL, NULL, 'day', '28 November 1899', 43, 'https://en.wikipedia.org/wiki/Battle_of_Modder_River'),
  ('Q263950', 'Battle of Elandslaagte', 'The Battle of Elandslaagte (21 October 1899) took place during the Second Boer War, and was one of the few decisive victories won by the British during the conflict. At the time, the Boers were invading Natal, and had occupied the railway station at Elandslaagte.', 1899, 10, 21, NULL, NULL, NULL, 'day', '21 October 1899', 45, 'https://en.wikipedia.org/wiki/Battle_of_Elandslaagte'),
  ('Q369859', 'Battle of Belmont', 'The Battle of Belmont was an engagement of the Second Boer War on 23 November 1899, where the British under Lord Methuen assaulted a Boer position on Belmont kopje. Methuen''s three brigades were on their way to raise the Boer siege of Kimberley.', 1899, 11, 23, NULL, NULL, NULL, 'day', '23 November 1899', 41, 'https://en.wikipedia.org/wiki/Battle_of_Belmont_(1899)'),
  ('Q431849', 'Battle of Stormberg', 'The Battle of Stormberg was a British assault on Stormberg Junction on 10 December 1899 during the Second Boer War. At that time, the Boers had taken control of Molten and the heights around Stormberg Junction, as part of their invasion of Cape Colony.', 1899, 12, 10, NULL, NULL, NULL, 'day', '10 December 1899', 51, 'https://en.wikipedia.org/wiki/Battle_of_Stormberg'),
  ('Q845845', 'Battle of Kraaipan', 'The Battle of Kraaipan was the first engagement of the Second Anglo-Boer War, fought at Kraaipan, South Africa on 12 October 1899. On the 11 October 1899 President Paul Kruger of the South African Republic in alliance with the Orange Free State declared war on the British.', 1899, 10, 13, NULL, NULL, NULL, 'day', '13 October 1899', 41, 'https://en.wikipedia.org/wiki/Battle_of_Kraaipan'),
  ('Q868249', 'Battle of Colenso', 'The Second Battle of Colenso, also known as the Battle of Colenso, was the third and final battle fought during the Black Week of the Second Boer War. It was fought between British and Boer forces from the independent South African Republic and Orange Free State in and around Colenso, Natal, South Africa on 15 December 1899.', 1899, 12, 15, NULL, NULL, NULL, 'day', '15 December 1899', 51, 'https://en.wikipedia.org/wiki/Second_Battle_of_Colenso'),
  ('Q1388058', 'Battle of Magersfontein', 'The Battle of Magersfontein ( MAH-khərss-fon-tayn) was fought on 11 December 1899, at Magersfontein, near Kimberley, South Africa, on the borders of the Cape Colony and the independent republic of the Orange Free State (now in Sol Plaatje Local Municipality, Northern Cape). British forces under Lieutenant General Lord Methuen were advancing north along the railway line from the Cape to relieve the siege of Kimberley, but their path was blocked at Magersfontein by a Boer force that was entrenched in the surrounding hills.', 1899, 12, 11, NULL, NULL, NULL, 'day', '11 December 1899', 55, 'https://en.wikipedia.org/wiki/Battle_of_Magersfontein'),
  ('Q1676845', 'Boer Wars', 'The military history of South Africa chronicles a vast time period and complex events from the dawn of history until the present time. It covers civil wars and wars of aggression and of self-defense both within South Africa and against it.', 1899, 10, 11, NULL, NULL, NULL, 'day', '11 October 1899', 70, 'https://en.wikipedia.org/wiki/Boer_Wars'),
  ('Q2090584', 'Siege of Mafeking', 'The siege of Mafeking was a 217-day siege battle for the town of Mafeking (now called Mahikeng) in South Africa during the Second Boer War from October 1899 to May 1900. The siege received considerable attention as Lord Edward Cecil, the son of the British prime minister, was in the besieged town, as also was Lady Sarah Wilson, a daughter of the Duke of Marlborough and aunt of Winston Churchill.', 1899, 10, 13, 1900, 5, 17, 'day', '13 October 1899 – 17 May 1900', 57, 'https://en.wikipedia.org/wiki/Siege_of_Mafeking'),
  ('Q2543997', 'Siege of Ladysmith', 'The siege of Ladysmith was a protracted engagement in the Second Boer War, taking place between 2 November 1899 and 28 February 1900 at Ladysmith, Natal. After the outbreak of war in October, Boer forces invaded neighbouring British colonies and rapidly surrounded the border towns of Ladysmith, Kimberly and Mafeking.', 1899, 11, 2, 1900, 2, 28, 'day', '2 November 1899 – 28 February 1900', 53, 'https://en.wikipedia.org/wiki/Siege_of_Ladysmith'),
  ('Q2888674', 'Battle of Graspan', 'The Battle of Graspan, also known as the Battle of Enslin, was an engagement in the Second Boer War near the Enslin railway station at Graspan kopje. The battle took place on November 25, 1899, between British forces led by Lord Methuen and Boers led by Koos de la Rey.', 1899, 11, 25, NULL, NULL, NULL, 'day', '25 November 1899', 37, 'https://en.wikipedia.org/wiki/Battle_of_Graspan'),
  ('Q2889085', 'Battle of Ladysmith', 'The Battle of Ladysmith, also known as the Battle of Lombard''s Kop, was one of the early engagements of the Second Boer War. A large British force which had concentrated at the garrison town of Ladysmith launched a sortie on 30 October 1899, against Boer armies which were slowly surrounding the town.', 1899, 10, 30, NULL, NULL, NULL, 'day', '30 October 1899', 41, 'https://en.wikipedia.org/wiki/Battle_of_Ladysmith'),
  ('Q736490', 'Battle of Vaal Krantz', 'The Battle of Vaal Krantz (Afrikaans: Slag van Vaalkrans, 5 - 7 February 1900) was the third failed attempt by General Redvers Buller''s British army to fight its way past Louis Botha''s army of Boer irregulars and lift the Siege of Ladysmith. The battle occurred during the Second Boer War.', 1900, 2, 5, 1900, 2, 7, 'day', '5 February 1900 – 7 February 1900', 43, 'https://en.wikipedia.org/wiki/Battle_of_Vaal_Krantz'),
  ('Q1072592', 'Battle of Spion Kop', 'The Battle of Spion Kop (Dutch: Slag bij Spionkop; Afrikaans: Slag van Spioenkop) was a military engagement between British forces and two Boer Republics, the South African Republic and the Orange Free State, during the campaign by the British to relieve the besieged city Ladysmith during the initial months of the Second Boer War. The battle was fought 23–24 January 1900 on the hilltop of Spioen Kop(a), about 38 km (24 mi) west-southwest of Ladysmith and resulted in a Boer victory.', 1900, 1, 23, 1900, 1, 24, 'day', '23 January 1900 – 24 January 1900', 52, 'https://en.wikipedia.org/wiki/Battle_of_Spion_Kop'),
  ('Q1767196', 'Battle of Bergendal', 'The Battle of Berg-en-dal (also known as the Battle of Belfast or Battle of Dalmanutha) took place in South Africa during the Second Anglo-Boer War. The battle was the last set-piece battle of the war, although the war was still to last another two years.', 1900, 8, 27, NULL, NULL, NULL, 'day', '27 August 1900', 39, 'https://en.wikipedia.org/wiki/Battle_of_Bergendal'),
  ('Q2237713', 'Battle of Paardeberg', 'The Battle of Paardeberg or Perdeberg ("Horse Mountain", 18–27 February 1900) was a major battle during the Second Anglo-Boer War. It was fought near Paardeberg Drift on the banks of the Modder River in the Orange Free State near Kimberley (now in Letsemeng Local Municipality, Free State).', 1900, 2, 18, 1900, 2, 27, 'day', '18 February 1900 – 27 February 1900', 50, 'https://en.wikipedia.org/wiki/Battle_of_Paardeberg'),
  ('Q2888144', 'Battle of Biddulphsberg', 'The Battle of Biddulphsberg was an engagement of the Second Boer War on May 29, 1900, and was part of the Advance on Pretoria. Troops of the 8th Division were stationed in the Southern regions of the Orange Free State in order to cover Lord Roberts'' advance on Transvaal, and to prevent the Orange Free State from falling back under Boer control.', 1900, 5, 29, NULL, NULL, NULL, 'day', '29 May 1900', 39, 'https://en.wikipedia.org/wiki/Battle_of_Biddulphsberg'),
  ('Q2888184', 'Battle of Bothaville', 'The Battle of Bothaville (Doornkraal) on 6 November 1900 was a rare defeat of Christiaan de Wet''s Boer commando at the hands of a force of British Mounted Infantry (MI).', 1900, 11, 6, NULL, NULL, NULL, 'day', '6 November 1900', 39, 'https://en.wikipedia.org/wiki/Battle_of_Bothaville'),
  ('Q2888406', 'Battle of Diamond Hill', 'The Battle of Diamond Hill (Donkerhoek) (Afrikaans: Slag van Donkerhoek) was an engagement of the Second Boer War that took place on 11 and 12 June 1900 in central Transvaal.', 1900, 6, 12, NULL, NULL, NULL, 'day', '12 June 1900', 39, 'https://en.wikipedia.org/wiki/Battle_of_Diamond_Hill'),
  ('Q2889543', 'Battle of Nooitgedacht', 'In the Battle of Nooitgedacht on 13 December 1900, Boer commandos led by Generals Koos de la Rey and Christiaan Beyers combined to deal a defeat to a British brigade under the command of Major General R. A. P. Clements during the Second Boer War.', 1900, 12, 13, NULL, NULL, NULL, 'day', '13 December 1900', 39, 'https://en.wikipedia.org/wiki/Battle_of_Nooitgedacht'),
  ('Q2889933', 'Battle of Sanna''s Post', 'The Battle of Sanna''s Post (a.k.a. Kroon Spruit) was an engagement fought during the Second Boer War (1899–1902) between the British Empire and the Boers of the two independent republics of the Orange Free State and the South African Republic.', 1900, 3, 31, NULL, NULL, NULL, 'day', '31 March 1900', 37, 'https://en.wikipedia.org/wiki/Sanna''s_Post'),
  ('Q2888152', 'Battle of Blood River Poort', 'In the Battle of Blood River Poort or Scheeper''s Nek on 17 September 1901 a Boer commando led by Louis Botha crushed a British force commanded by Major Hubert Gough during the Second Boer War.', 1901, 9, 17, NULL, NULL, NULL, 'day', '17 September 1901', 39, 'https://en.wikipedia.org/wiki/Battle_of_Blood_River_Poort'),
  ('Q3274751', 'Bambatha Rebellion', 'The Bambatha Rebellion (also known as the Zulu Rebellion) was a 1906 uprising against colonial rule in the British colony of Natal led by the Zulu chief Bhambatha, who lived in the Mpanza Valley (now a district near Greytown). It was sparked by unpopular taxation policies levied by the Natal colonial administration, which exacerbated ongoing economic crises.', 1906, NULL, NULL, NULL, NULL, NULL, 'year', '1906', 48, 'https://en.wikipedia.org/wiki/Bambatha_Rebellion'),
  ('Q767368', 'Maritz Rebellion', 'The Maritz rebellion, also known as the Third Boer War, or the Five Shilling rebellion, was an armed pro-German insurrection in South Africa in 1914, at the start of World War I. It was led by Boers who supported the re-establishment of the South African Republic in the Transvaal. Many members of the South African government were themselves Boers who had fought with the Maritz rebels against the British in the Second Boer War, which had ended twelve years earlier.', 1914, 9, 15, 1915, 2, 4, 'day', '15 September 1914 – 4 February 1915', 59, 'https://en.wikipedia.org/wiki/Maritz_rebellion'),
  ('Q3070782', 'Rand Rebellion', 'The Rand Rebellion (Afrikaans: Rand-rebellie; also known as the 1922 Miners'' strike and the Rand Revolt) was an armed uprising of White Syndicalists, Communists, and Nationalists in the Witwatersrand region of South Africa, in March 1922. Following a drop in the global price of gold from 130 shillings (£6 10s) per fine troy ounce in 1919 to 95s/oz (£4 15s) in December 1921, the mining companies owned by the Randlords tried to cut their operating costs by decreasing wages, and by promoting black mine workers – who were paid lower wages – to skilled and supervisory positions.', 1921, 12, 28, 1922, 3, NULL, 'day', '28 December 1921 – March 1922', 43, 'https://en.wikipedia.org/wiki/Rand_Rebellion'),
  ('Q8698', 'Great Depression', 'The Great Depression was a severe global economic downturn from 1929 to 1939. The period was marked by high rates of unemployment and poverty, drastic reductions in industrial production and international trade, and widespread bank and business failures around the world.', 1929, 10, 29, 1941, NULL, NULL, 'day', '29 October 1929 – 1941', 93, 'https://en.wikipedia.org/wiki/Great_Depression'),
  ('Q518753', 'Sharpeville massacre', 'The Sharpeville massacre occurred on 21 March 1960, when police opened fire on a crowd of people who had assembled outside the police station in the township of Sharpeville in the then Transvaal Province of the then Union of South Africa (today part of Gauteng) to protest against the apartheid system and its pass laws. A crowd of approximately 5,000 people gathered in Sharpeville that day in response to the call made by the Pan-Africanist Congress to leave their pass-books at home and to demand that the police arrest them for contravening the pass laws.', 1960, 3, 21, NULL, NULL, NULL, 'day', '21 March 1960', 72, 'https://en.wikipedia.org/wiki/Sharpeville_massacre'),
  ('Q153081', 'Soweto uprising', 'The Soweto uprising, also known as the Soweto riots or the Soweto rebellion, was a series of demonstrations and protests led by black school children in South Africa during apartheid that began on the morning of 16 June 1976. Students from various schools began to protest in the streets of the Soweto township in response to the introduction of Afrikaans, considered by many black South Africans as the "language of the oppressor", as the medium of instruction in black schools.', 1976, 6, 16, NULL, NULL, NULL, 'day', '16 June 1976', 70, 'https://en.wikipedia.org/wiki/Soweto_uprising'),
  ('Q950273', '1986 Mozambican Tupolev Tu-134 crash', 'On 19 October 1986, a Tupolev Tu-134 jetliner with a Soviet crew carrying President Samora Machel and 43 others from Mbala, Zambia to the Mozambican capital Maputo crashed at Mbuzini, South Africa. Nine passengers and one crew member survived the crash, but President Machel and 33 others died, including several ministers and senior officials of the Mozambican government.', 1986, 10, 19, NULL, NULL, NULL, 'day', '19 October 1986', 51, 'https://en.wikipedia.org/wiki/1986_Mozambican_Tupolev_Tu-134_crash'),
  ('Q1770923', 'Bisho massacre', 'The Bisho massacre occurred on 7 September 1992 in Bisho, in the then nominally independent homeland of Ciskei which is now part of the Eastern Cape in South Africa. Twenty-eight African National Congress (ANC) supporters and one soldier were shot dead by the Ciskei Defence Force (CDF) during a protest march when they attempted to enter Bisho (now renamed to Bhisho) to demand the reincorporation of Ciskei into South Africa nearly six months after the 1992 South African apartheid referendum was held.', 1992, 9, 7, NULL, NULL, NULL, 'day', '7 September 1992', 39, 'https://en.wikipedia.org/wiki/Bisho_massacre'),
  ('Q3297426', 'Boipatong massacre', 'The Boipatong massacre took place on the night of 17 June 1992 in the township of Boipatong, South Africa.', 1992, 6, 17, NULL, NULL, NULL, 'day', '17 June 1992', 41, 'https://en.wikipedia.org/wiki/Boipatong_massacre'),
  ('Q7565818', 'South African apartheid referendum, 1992', 'A referendum on ending apartheid was held in South Africa on 17 March 1992. The referendum was limited to white South African voters, who were asked whether or not they supported the negotiated reforms begun by State President F. W. de Klerk two years earlier, in which he proposed to end the apartheid system that had been implemented since 1948.', 1992, 3, 17, NULL, NULL, NULL, 'day', '17 March 1992', 47, 'https://en.wikipedia.org/wiki/1992_South_African_apartheid_referendum'),
  ('Q130754', '2004 Indian Ocean earthquake', 'On 26 December 2004, at 07:58:53 local time (UTC+7), a Mw 9.2–9.3 earthquake struck with its epicenter off the west coast of Aceh, in northern Sumatra, Indonesia. The undersea megathrust earthquake, known in the scientific community as the Sumatra–Andaman earthquake, was caused by a rupture along the fault boundary between the Burma plate and the Indian plate, and reached a maximum Mercalli intensity of IX in some areas.', 2004, 12, 26, NULL, NULL, NULL, 'day', '26 December 2004', 85, 'https://en.wikipedia.org/wiki/2004_Indian_Ocean_earthquake_and_tsunami'),
  ('Q1203203', 'Marikana miners'' strike', 'The Marikana massacre was the killing of thirty-four miners by the South African Police Service (SAPS) on 16 August 2012 during a six-week wildcat strike at the Lonmin platinum mine at Marikana near Rustenburg in South Africa''s North West province. The massacre constituted the most lethal use of force by South African security forces against civilians since the Soweto uprising in 1976 and has been compared to the 1960 Sharpeville massacre.', 2012, 8, 16, 2012, 9, 20, 'day', '16 August 2012 – 20 September 2012', 62, 'https://en.wikipedia.org/wiki/Marikana_massacre'),
  ('Q21206469', '#FeesMustFall', '#FeesMustFall was a student-led protest movement that began in mid-October 2015 in South Africa. The goals of the movement were to stop increases in student fees as well as to increase government funding of universities.', 2015, 10, 12, NULL, NULL, NULL, 'day', '12 October 2015', 43, 'https://en.wikipedia.org/wiki/FeesMustFall'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q106543515', 'Table Mountain Fire (2021)', 'The 2021 Table Mountain fire (also known as the Rhodes Memorial fire or Cape Town fire) was a major fire that started on 18 April 2021 in and around Table Mountain National Park and the neighbourhoods of Newlands, Rosebank, Mowbray and Rondebosch in Cape Town, South Africa. The damage to sites in the Table Mountain area included the Rhodes Memorial, where a restaurant burned down; the upper campus of the University of Cape Town (UCT), where the Special Collections library was gutted; and Mostert''s Mill, a historic windmill that burned down.', 2021, 4, 18, NULL, NULL, NULL, 'day', '18 April 2021', 50, 'https://en.wikipedia.org/wiki/2021_Table_Mountain_fire'),
  ('Q107514094', '2021 South African unrest', 'The 2021 South African unrest, also known as the July 2021 riots, the Zuma unrest or Zuma riots, was a wave of civil unrest that occurred in South Africa''s KwaZulu-Natal and Gauteng provinces from 9 to 18 July 2021, sparked by the imprisonment of former President Jacob Zuma for contempt of court. Resulting protests against the incarceration triggered wider rioting and looting, much of it said to be undertaken by people not in support of Zuma and fuelled by job layoffs and economic inequality worsened by the COVID-19 pandemic policies.', 2021, 7, 9, 2021, 7, 17, 'day', '9 July 2021 – 17 July 2021', 58, 'https://en.wikipedia.org/wiki/2021_South_African_unrest'),
  ('Q111598844', '2022 KwaZulu-Natal floods', 'In April 2022, days of heavy rain across KwaZulu-Natal in southeastern South Africa led to deadly floods. Particularly hard-hit were areas in and around Durban.', 2022, 4, 8, NULL, NULL, NULL, 'day', '8 April 2022', 56, 'https://en.wikipedia.org/wiki/2022_KwaZulu-Natal_floods'),
  ('Q117039336', '2023 South Africa floods', 'There were floods in South Africa in February and March, then again in September and again in December 2023.', 2023, NULL, NULL, NULL, NULL, NULL, 'year', '2023', 39, 'https://en.wikipedia.org/wiki/2023_South_Africa_floods'),
  ('Q118316106', '2023 Africa floods', 'From February to late-December 2023, floods killed over 2,600 people in 15 countries across Africa.', 2023, 2, 5, NULL, NULL, NULL, 'day', '5 February 2023', 43, 'https://en.wikipedia.org/wiki/2023_Africa_floods'),
  ('Q122146423', '80 Albert Street Fire', 'On 31 August 2023 at around 01:30 SAST, a fire engulfed an illegally occupied government-owned building in Johannesburg, South Africa; 77 people were killed and 88 others were injured. It was one of the deadliest fires in South African history.', 2023, 8, 31, NULL, NULL, NULL, 'day', '31 August 2023', 64, 'https://en.wikipedia.org/wiki/2023_Johannesburg_building_fire');
